    "id": "cm-algo-6-1",
    "title": "Procedure 6.1: PUSH(STACK, TOP, MAXSTK, ITEM) — Inserting onto Stack",
    "book_reference": "Lipschutz & Seymour, Data Structures, Revised 4th Ed., Chapter 6: Stacks, Queues, Recursion, Procedure 6.1, Page 229",
    "topic_tag": "Stacks",
    "content_type": "algorithm",
    "difficulty": "easy",
